def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    try:
        if value is None:
            return None
        if not isinstance(value, timedelta):
            raise TypeError(f"Expected datetime.timedelta, got {type(value).__name__}")
        sec = float(value.total_seconds())
        return int(sec) if sec.is_integer() else sec
    except Exception as exc:
        raise ValueError(f"Failed to dehydrate timedelta: {exc}")

def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value: The time instance to dehydrate.
    :type value: Time
    :return: A string representation of the time or None if value is None.
    """
    # Nothing to do for a missing value
    if value is None:
        return None

    try:
        # Prefer a native ISO format if available
        if hasattr(value, "isoformat"):
            # The ISO format includes timezone info if present
            return value.isoformat()
        # Fallback: use string representation
        return str(value)
    except Exception as exc:
        # Any conversion error is surfaced as a ValueError
        raise ValueError(f"Unable to dehydrate time value: {exc}") from exc

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    try:
        if value is None:
            return None
        # If already a serialisable tuple or list, just return as a tuple.
        if isinstance(value, (tuple, list)):
            return tuple(value)
        # Standard Point objects expose .x and .y attributes.
        if hasattr(value, 'x') and hasattr(value, 'y'):
            return {'x': getattr(value, 'x'), 'y': getattr(value, 'y')}
        # Some implementations might be iterable.  Try to unpack.
        if hasattr(value, '__iter__'):
            coords = list(value)
            if len(coords) >= 2:
                return {'x': coords[0], 'y': coords[1]}
        raise TypeError(f"Unsupported type for dehydration: {type(value)!r}")
    except Exception as exc:
        raise ValueError(f"Error dehydrating Point: {exc}") from exc

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Try to locate a dictionary-like attribute containing the record data
        record = getattr(self, "_record", None)
        if record is None:
            record = getattr(self, "record", None)
        if record is None:
            record = getattr(self, "data", None)
        # As a last resort, use the instance's __dict__
        if record is None:
            record = getattr(self, "__dict__", None)

        if record is None:
            raise AttributeError("No record attribute found on the instance")

        if isinstance(record, dict):
            return list(record.keys())
        # Attempt to use the object's attributes if not a dict
        try:
            return list(vars(record).keys())
        except Exception:
            raise TypeError("Record attribute is not a dictionary or attribute container")
    except Exception as e:
        raise ValueError(f"Unable to retrieve keys from record: {e}") from e

def index(self, key):
    """Return the index of the given item.

    Parameters:
        key: A key or value to search for in ``self``.

    Returns:
        int: The index of the first occurrence of ``key`` in ``self``.

    Raises:
        ValueError: If ``key`` is not found.
        TypeError: If ``self`` is not an iterable or the operation fails.
    """
    # If ``self`` already implements an efficient ``index`` method (e.g., list),
    # use it first to avoid an unnecessary manual loop.
    try:
        if hasattr(self, "index") and callable(self.index):
            return self.index(key)
    except Exception:
        # If ``index`` raises its own exception (e.g., wrong type), fall back.
        pass

    # Manual fallback: iterate over ``self`` and locate the item.
    try:
        for idx, item in enumerate(self):
            if item == key:
                return idx
    except TypeError as exc:
        # ``self`` is not iterable.
        raise TypeError(f"Object {self!r} is not iterable") from exc

    # If we reach here, the key was not found.
    raise ValueError(f"{key!r} is not in {self!r}")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Resolve the collection of items.  We expect `self` to provide an
    # attribute called ``items`` which contains an iterable of key/value
    # pairs, e.g. a list of tuples or a dict-like object.
    try:
        items = getattr(self, "items", None)
        if items is None:
            raise AttributeError("Record object has no 'items' attribute")

        # Normalise keys to an iterable (handle the case where a single
        # iterable is passed as a positional argument).
        if len(keys) == 1 and isinstance(keys[0], (list, tuple, set)):
            keys = tuple(keys[0])

        # If no keys were supplied, return all values.
        if not keys:
            # ``items`` might be a dict or an iterable of tuples.
            if isinstance(items, dict):
                return list(items.values())
            else:
                return [v for _, v in items]

        result = []
        for key in keys:
            # Support numeric indices – we interpret any int as a
            # position index in the collection.
            if isinstance(key, int):
                try:
                    result.append(items[key][1] if not isinstance(items, dict) else list(items.values())[key])
                except IndexError as e:
                    raise IndexError(f"Index {key} out of range") from e
            else:
                # Assume a key lookup.  For dicts this is straightforward,
                # for a list of tuples we search sequentially.
                if isinstance(items, dict):
                    try:
                        result.append(items[key])
                    except KeyError as e:
                        raise KeyError(f"Key {key!r} not found") from e
                else:
                    found = False
                    for k, v in items:
                        if k == key:
                            result.append(v)
                            found = True
                            break
                    if not found:
                        raise KeyError(f"Key {key!r} not found")
        return result

    except Exception as exc:
        # Preserve the stack trace but provide a more contextual error.
        raise ValueError(f"Failed to retrieve values from record: {exc}") from exc

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Collect field names in a deterministic order
    try:
        # Prefer an explicit order attribute if available
        field_names = list(getattr(self, "__field_order__", []))
    except Exception:
        field_names = []

    # Fallback: use all attribute names that don't start with underscore
    if not field_names:
        field_names = [k for k in vars(self).keys() if not k.startswith("_")]

    # If no specific keys requested, return all
    if not keys:
        return {k: getattr(self, k) for k in field_names}

    result = {}
    for k in keys:
        if isinstance(k, int):
            # Treat as positional index
            if k < 0 or k >= len(field_names):
                raise IndexError(f"Index {k} out of bounds for record with {len(field_names)} fields")
            field = field_names[k]
            result[field] = getattr(self, field)
        else:
            # Treat as field name
            if k in field_names:
                result[k] = getattr(self, k)
            else:
                result[k] = None
    return result

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    # --- validation -----------------------------------------------------
    if not isinstance(name, str) or not name:
        raise ValueError("`name` must be a non-empty string")
    if not isinstance(fields, (list, tuple)):
        raise TypeError("`fields` must be a list or tuple of field definitions")
    if not isinstance(srid_map, dict):
        raise TypeError("`srid_map` must be a dictionary mapping srid to CRS information")

    # --- build attribute dictionary --------------------------------------
    attrs = {}
    for field in fields:
        if isinstance(field, str):
            attrs[field] = None
        elif isinstance(field, (list, tuple)) and len(field) == 2:
            key, default = field
            if not isinstance(key, str):
                raise TypeError(f"Field name {key!r} must be a string")
            attrs[key] = default
        else:
            raise ValueError(f"Invalid field description: {field!r}")

    # --- constructor -----------------------------------------------------
    def __init__(self, x, y, srid=None, **kwargs):
        # Call parent constructor
        try:
            super(self.__class__, self).__init__(x, y)
        except Exception as exc:
            raise RuntimeError(f"Failed to initialize base Point: {exc}") from exc

        # Validate and set SRID
        if srid is not None:
            if srid not in srid_map:
                raise ValueError(f"SRID {srid!r} not found in provided srid_map")
            self.srid = srid
        else:
            self.srid = None

        # Initialise custom fields
        for key, value in kwargs.items():
            if key in attrs:
                setattr(self, key, value)
            else:
                raise AttributeError(f"Unexpected attribute {key!r}")

    attrs['__init__'] = __init__

    # --- representation --------------------------------------------------
    def __repr__(self):
        field_values = ", ".join(f"{k}={getattr(self, k)!r}" for k in attrs if k not in ('x', 'y', 'srid'))
        return f"<{name} ({self.x}, {self.y}, srid={self.srid}{', ' if field_values else ''}{field_values})>"

    attrs['__repr__'] = __repr__

    # --- create the class ------------------------------------------------
    try:
        new_cls = type(name, (Point,), attrs)
    except Exception as exc:
        raise RuntimeError(f"Failed to create class {name!r}: {exc}") from exc

    return new_cls

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def _decorator(func):
        import functools
        import warnings
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(f"Deprecated function {func.__name__}: {message}", DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return _decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("input must be a string")
    s = s.strip()
    if not s:
        return ()
    # Split on any non-digit character
    import re
    parts = re.split(r'\D+', s)
    numbers = []
    for part in parts:
        if part:
            try:
                numbers.append(int(part))
            except ValueError:
                # ignore non-numeric fragments
                pass
    return tuple(numbers)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            try:
                k = key(args, kwargs)
            except Exception as e:
                raise ValueError(f"Key function failed: {e}") from e

            if lock:
                try:
                    with lock:
                        if k in cache:
                            return cache[k]
                        result = func(*args, **kwargs)
                        cache[k] = result
                    return result
                except Exception as e:
                    raise RuntimeError(f"Cache access failed: {e}") from e
            else:
                try:
                    if k in cache:
                        return cache[k]
                    result = func(*args, **kwargs)
                    cache[k] = result
                    return result
                except Exception as e:
                    raise RuntimeError(f"Cache access failed: {e}") from e

        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if not isinstance(maxsize, int):
        raise TypeError("maxsize must be an integer")
    if maxsize < 0:
        raise ValueError("maxsize must be >= 0")
    if maxsize == 0:
        # No caching if maxsize is zero
        def decorator(func):
            return func
        return decorator

    def _make_key(args, kwargs, typed):
        key = args
        if kwargs:
            # Order kwargs for consistency
            key += tuple(sorted(kwargs.items()))
        if typed:
            key += tuple(type(v) for v in args)
            key += tuple(type(v) for v in kwargs.values())
        return key

    def decorator(func):
        cache = {}
        # We maintain an OrderedDict to keep track of usage order.
        usage = collections.OrderedDict()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs, typed)
            if key in cache:
                # Move key to end to mark it as most recent
                usage.move_to_end(key)
                return cache[key]
            # Compute result
            result = func(*args, **kwargs)
            cache[key] = result
            usage[key] = None  # actual result stored separately
            # If cache is over capacity, evict most recent (MRU) item
            if len(cache) > maxsize:
                # pop the most recent key
                mru_key, _ = usage.popitem(last=True)
                del cache[mru_key]
            return result

        wrapper.cache_info = functools._make_cache_info(
            len(cache), maxsize, "mru_cache", 0
        )
        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    from collections import defaultdict, OrderedDict
    import functools
    import inspect

    def make_hashable(obj):
        """Recursively convert unhashable objects to hashable equivalents."""
        if isinstance(obj, (list, tuple)):
            return tuple(make_hashable(e) for e in obj)
        if isinstance(obj, dict):
            return tuple(sorted((k, make_hashable(v)) for k, v in obj.items()))
        if isinstance(obj, set):
            return tuple(sorted(make_hashable(e) for e in obj))
        # Primitive types are already hashable
        return obj

    def lfu_wrapper(func):
        cache = {}
        freq = defaultdict(OrderedDict)  # freq -> keys maintaining order
        minfreq = [0]  # use list to allow mutation in nested scope

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Prepare key
            try:
                key = make_hashable(args)
                kw_key = make_hashable(kwargs)
                key = (key, kw_key, typed)
            except TypeError as e:
                # If arguments cannot be hashed, fall back to no caching
                try:
                    return func(*args, **kwargs)
                except Exception as exc:
                    raise exc
            # Hit
            if key in cache:
                value, curfreq = cache[key]
                # Update frequency
                del freq[curfreq][key]
                if not freq[curfreq]:
                    del freq[curfreq]
                    if minfreq[0] == curfreq:
                        minfreq[0] += 1
                newfreq = curfreq + 1
                freq[newfreq][key] = None
                cache[key] = (value, newfreq)
                return value
            # Miss
            try:
                result = func(*args, **kwargs)
            except Exception as exc:
                # Do not cache exceptions
                raise exc
            # Insert new entry
            if len(cache) >= maxsize and maxsize > 0:
                # Evict least frequently used key
                oldest_freq = minfreq[0]
                oldest_key, _ = freq[oldest_freq].popitem(last=False)
                if not freq[oldest_freq]:
                    del freq[oldest_freq]
                del cache[oldest_key]
            cache[key] = (result, 1)
            freq[1][key] = None
            minfreq[0] = 1
            return result

        return wrapper

    return lfu_wrapper

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    # Ensure self behaves like a dictionary
    if not hasattr(self, "__iter__") or not hasattr(self, "keys"):
        raise TypeError(f"popitem() called on unsupported object of type {type(self).__name__}")

    # Attempt to fetch the first inserted key
    for key in self:
        break
    else:
        raise KeyError("popitem(): dictionary is empty")

    value = self[key]
    try:
        del self[key]
    except KeyError:
        # The key might have been removed concurrently; treat this as an error
        raise KeyError(f"Key {key!r} not found for pop")

    return key, value

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    if key in self:
        return self[key]
    self[key] = default
    return default

def get(self, key, default=None):
        """
        D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
        """
        # Attempt to retrieve the value associated with 'key'.
        # If the key is not present or an exception occurs, return the default.
        try:
            return self[key]
        except (KeyError, TypeError):
            return default

@staticmethod
def file_to_textbuffer(file_name, encoding):
    """
    Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
    CAUTION : This will read the whole file IN MEMORY.
    :param file_name: File name.
    :type file_name: str
    :param encoding: Encoding to use.
    :type encoding: str
    :return: A text buffer or None in case of error.
    :rtype str
    """
    # Validate input types; if invalid return None
    if not isinstance(file_name, str) or not isinstance(encoding, str):
        return None

    try:
        with open(file_name, 'r', encoding=encoding) as f:
            return f.read()
    except Exception:
        return None

