def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    try:
        import sys
    except ImportError:
        # Fallback if sys cannot be imported – return the actual class
        return self.__class__
    cls = self.__class__
    name = cls.__name__
    for suffix in ("Py", "Fallback"):
        if name.endswith(suffix):
            name = name[: -len(suffix)]
            break
    try:
        module = sys.modules.get(cls.__module__, None)
        if module is not None:
            return getattr(module, name, cls)
    except Exception:
        pass
    return cls

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ...   ['x', 'y', 'z'],
    ...   ['q', 'z'],
    ...   [1, 3, 5],
    ...   ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """

    # Validate input
    if not isinstance(orderings, (list, tuple)):
        raise TypeError("orderings must be a list or tuple of iterables")

    # Flatten all unique items and record first appearance index for tie-breaking
    first_index = {}
    index_counter = 0
    for sub in orderings:
        if not hasattr(sub, "__iter__"):
            raise TypeError("each ordering must be iterable")
        for item in sub:
            if item not in first_index:
                first_index[item] = index_counter
                index_counter += 1

    # Build graph edges: for each pair of consecutive elements in each ordering
    adj = {item: set() for item in first_index}
    indegree = {item: 0 for item in first_index}
    for sub in orderings:
        for a, b in zip(sub, sub[1:]):
            if b not in adj[a]:
                adj[a].add(b)
                indegree[b] += 1

    # Kahn's algorithm with deterministic tie-breaking
    import heapq
    heap = []
    for item, deg in indegree.items():
        if deg == 0:
            heapq.heappush(heap, (first_index[item], item))

    result = []
    while heap:
        _, node = heapq.heappop(heap)
        result.append(node)
        for neigh in adj[node]:
            indegree[neigh] -= 1
            if indegree[neigh] == 0:
                heapq.heappush(heap, (first_index[neigh], neigh))

    # If not all nodes were processed, there was a cycle
    if len(result) != len(first_index):
        raise ValueError("Cycle detected in ordering constraints; cannot merge")

    return result)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError(f"Expected a list or tuple of classes, got {type(classes)!r}")
    minimal = []
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"Element {cls!r} is not a class type")
        # skip if a more specific subclass already recorded
        if any(issubclass(existing, cls) for existing in minimal):
            continue
        # remove any more general superclasses that are already in the minimal list
        minimal = [existing for existing in minimal if not issubclass(cls, existing)]
        minimal.append(cls)
    return minimal

def names(self, all=False):
    """Return the attribute names defined by the interface."""
    # If `all` is True, return every attribute present in the instance,
    # regardless of whether it is part of the interface.
    # Otherwise, return only the attributes defined on the class
    # (excluding private and callable attributes) which represent
    # the interface contract for this object.
    try:
        if all:
            # instance dictionary contains all instance attributes
            return list(self.__dict__.keys())

        # Use the class's dict to get attributes that belong to the interface.
        interface_attrs = []
        for name, obj in vars(self.__class__).items():
            # Skip private and special attributes
            if name.startswith('_'):
                continue
            # Skip methods, properties with a getter, and other callables
            if callable(obj):
                continue
            # Properties are descriptors; include them if they have a fget
            if isinstance(obj, property):
                if obj.fget is not None:
                    interface_attrs.append(name)
                continue
            # Regular data attributes declared in the class
            interface_attrs.append(name)

        return interface_attrs
    except Exception as exc:
        # Unexpected errors should be surfaced as a RuntimeError
        raise RuntimeError(f"Unable to retrieve interface names: {exc}") from exc

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    # Ensure output is a list
    if output is None:
        output = []

    try:
        iter(sequence)
    except TypeError:
        raise TypeError(f"Expected an iterable for 'sequence', got {type(sequence).__name__}")

    for item in sequence:
        # Treat strings and bytes as atomic values, not as iterables to expand
        if isinstance(item, (list, tuple)):
            _normalizeargs(item, output)
        else:
            output.append(item)

    return output

def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    try:
        import os
        if os.environ.get('PURE_PYTHON'):
            return False
    except Exception:
        # If os module is unavailable for some reason, ignore the check
        pass

    try:
        import sys
        if getattr(sys, 'implementation', None) and sys.implementation.name.lower() == 'pypy':
            return False
    except Exception:
        # If sys.implementation is not available, ignore the check
        pass

    return True

def _c_optimizations_ignored(self):
    """The opposite of `_c_optimizations_required`."""
    try:
        required = self._c_optimizations_required()
    except Exception:
        # If the required method is missing or fails, assume no optimization is required
        required = False
    return not required

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset context
    self.context = {}

    # Reinitialize bins
    # If an explicit initial_value is available, use it
    if hasattr(self, "initial_value") and self.initial_value is not None:
        try:
            if isinstance(self.bins, dict):
                self.bins = {k: self.initial_value for k in self.bins}
            elif isinstance(self.bins, (list, tuple)):
                self.bins = [self.initial_value] * len(self.bins)
            else:
                # Fallback: just overwrite with the value itself
                self.bins = self.initial_value
        except AttributeError:
            # If bins haven't been set yet, just ignore
            pass
    else:
        # No explicit initial_value: call make_bins() if available
        try:
            if hasattr(self, "make_bins"):
                self.bins = self.make_bins()
        except Exception:
            # In case make_bins fails or is missing, set to an empty list
            self.bins = []

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic input validation
    if bins is None or edges is None:
        raise ValueError("bins and edges must not be None")
    try:
        n_bins = len(bins)
        n_edges = len(edges)
    except TypeError:
        raise TypeError("bins and edges must be sequences")
    if n_bins == 0:
        return 0.0
    if n_edges != n_bins + 1:
        raise ValueError(
            f"Number of edges ({n_edges}) must be one more than number of bins ({n_bins})"
        )

    total = 0.0
    for value, left, right in zip(bins, edges, edges[1:]):
        try:
            width = right - left
        except TypeError as exc:
            raise TypeError(f"Edge values must support subtraction: {exc}") from exc
        try:
            total += value * width
        except TypeError as exc:
            raise TypeError(f"Bin values must support multiplication: {exc}") from exc
    return float(total)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        if seq is None:
            return False
        if isinstance(seq, FillRequest):
            return True
        if isinstance(seq, Source):
            return False
        if isinstance(seq, (str, bytes)):
            return False
        for item in seq:
            if isinstance(item, FillRequest):
                return True
        return False
    except Exception:
        return False

