def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both arguments must be dictionaries")

    # If recursion depth has been exhausted, return an empty dict
    if level == 0:
        return {}

    result = {}
    for key, value in d1.items():
        if key not in d2:
            # Key exists only in d1 – include it as is
            result[key] = value
        else:
            d2_value = d2[key]
            # Both values are dictionaries and we are allowed to recurse
            if isinstance(value, dict) and isinstance(d2_value, dict) and (level > 1 or level == -1):
                sub = difference(value, d2_value, level - 1 if level > 0 else -1)
                if sub:
                    result[key] = sub
            else:
                # For level 1 we include differing scalar values
                if level == 1 and value != d2_value:
                    result[key] = value
    return result

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate weight
    try:
        w = float(weight)
    except Exception as exc:
        raise TypeError("weight must be a numeric value") from exc

    # Convert coordinate to numpy array (assumes numpy is available)
    try:
        c_arr = np.array(coord, dtype=float)
    except Exception as exc:
        raise TypeError("coord must be an iterable of numeric values") from exc

    # Ensure correct dimensionality
    if c_arr.ndim != 1 or len(c_arr) != len(self.edges):
        raise ValueError("coord must have length equal to histogram dimensionality")

    indices = []
    for dim_val, edges_dim in zip(c_arr, self.edges):
        # Check if value is within the valid range
        if dim_val < edges_dim[0] or dim_val > edges_dim[-1]:
            return  # Ignore coordinates outside the histogram

        # Find the bin index for this dimension
        idx = np.searchsorted(edges_dim, dim_val, side="right") - 1

        # Bounds check for the found index
        if idx < 0 or idx >= self.data.shape[indices.__len__()]:
            return

        indices.append(int(idx))

    # Increment the histogram bin
    try:
        self.data[tuple(indices)] += w
    except Exception as exc:
        raise RuntimeError(f"Failed to fill histogram due to: {exc}") from exc

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    messages = []

    # Validate each key and value
    for key, value in labels.items():
        # Check key type
        if not isinstance(key, (str, bytes)):
            messages.append({repr(key): 'expected string or bytes-like object'})
        else:
            # Check key against regex
            if not LABEL_KEY_REGEX.match(key):
                messages.append(
                    {
                        key: f"Label key '{key}' does not match the regex [{LABEL_KEY_REGEX.pattern}]"
                    }
                )

        # Check value type
        if not isinstance(value, (str, bytes)):
            messages.append({repr(value): 'expected string or bytes-like object'})
        else:
            # Check value against regex
            if not LABEL_VALUE_REGEX.match(value):
                messages.append(
                    {
                        value: f"Label value '{value}' does not match the regex [{LABEL_VALUE_REGEX.pattern}]"
                    }
                )

    # Raise a ValidationError if any issues were found
    if messages:
        raise ValidationError(messages=messages)

