def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        # Ensure the application has the expected structure
        if not hasattr(app, 'spec'):
            raise AttributeError("The provided application object does not have a 'spec' attribute")
        manifest = getattr(app.spec, 'manifest', None)
        if manifest is None:
            return {}
    except Exception as exc:
        raise RuntimeError(f"Failed to access application spec: {exc}") from exc

    default_schemas = {}

    for resource in manifest:
        try:
            if not isinstance(resource, dict):
                continue
            kind = resource.get('kind')
            if not kind:
                continue
            # Skip kinds that already have a custom schema defined
            custom_schema = None
            if hasattr(app.spec, 'observer_schemas'):
                custom_schema = app.spec.observer_schemas.get(kind)
            if custom_schema:
                continue
            # Construct a very generic observer schema
            default_schema = {
                "type": "object",
                "properties": {
                    "apiVersion": {"type": "string"},
                    "kind": {"type": "string"},
                    "metadata": {"type": "object"},
                    "status": {"type": "object"},
                },
                "required": ["apiVersion", "kind", "metadata"],
            }
            default_schemas[kind] = default_schema
        except Exception as e:
            # Skip problematic resources but don't fail the whole operation
            continue

    # Attach the generated schemas back to the application spec
    try:
        if hasattr(app.spec, 'observer_schemas'):
            app.spec.observer_schemas.update(default_schemas)
        else:
            app.spec.observer_schemas = default_schemas
    except Exception as exc:
        raise RuntimeError(f"Failed to update observer schemas in the application spec: {exc}") from exc

    return default_schemas

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        import os, re
    except Exception:
        # Cannot import necessary modules
        return False

    def _has_ocfl_root(fs):
        """Check for .ocfl-root presence in a generic FS object."""
        try:
            return fs.isfile('.ocfl-root')
        except Exception:
            return False

    # Handle string path (filesystem)
    if isinstance(path, str):
        if not os.path.isdir(path):
            return False
        root_file = os.path.join(path, '.ocfl-root')
        if not os.path.isfile(root_file):
            return False
        try:
            with open(root_file, 'r', encoding='utf-8') as f:
                header_present = any(line.strip().startswith('path=') for line in f)
            if not header_present:
                return False
        except Exception:
            return False
        objects_dir = os.path.join(path, 'objects')
        if not os.path.isdir(objects_dir):
            return False
    else:
        # Assume a pyfs root-like object
        if not hasattr(path, 'dirsize') and not hasattr(path, 'listdir'):
            return False
        try:
            if not _has_ocfl_root(path):
                return False
            if not path.isdir('objects'):
                return False
        except Exception:
            return False

    return True

