def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Ensure inventory is a mapping
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary, got %s" % type(inventory).__name__)

    # --- Helper: basic sanity check on a version string ---
    def _valid_version(v):
        if not isinstance(v, str):
            return False
        # Consider anything containing at least one dot and a numeric prefix
        parts = v.split('.')
        return len(parts) >= 2 and all(part.isdigit() for part in parts if part != '')

    # Extract spec version if requested
    if extract_spec_version:
        # Some inventory sources might store the type under 'type' or '@type'
        inv_type = inventory.get('type') or inventory.get('@type')
        if _valid_version(inv_type):
            self.spec_version = inv_type
        else:
            # No valid type; fall back on existing spec_version
            if not hasattr(self, 'spec_version'):
                raise AttributeError("Instance has no 'spec_version' attribute and a valid type could not be extracted")
            # otherwise keep self.spec_version unchanged

    # Basic inventory structure checks
    required_keys = {'elements', 'attributes', 'types'}
    missing = required_keys - inventory.keys()
    if missing:
        raise ValueError(f"Inventory missing required top-level keys: {', '.join(sorted(missing))}")

    # Validate elements
    elements = inventory.get('elements', {})
    if not isinstance(elements, dict):
        raise TypeError("Inventory 'elements' must be a dictionary")
    for name, elem_def in elements.items():
        if not isinstance(elem_def, dict):
            raise TypeError(f"Element definition for '{name}' must be a dictionary")
        if 'class' not in elem_def:
            raise ValueError(f"Element '{name}' is missing required 'class' key")
        cls = elem_def['class']
        if not (isinstance(cls, type) and issubclass(cls, AbstractElement)):
            raise TypeError(f"Element '{name}' class must be a subclass of AbstractElement")

    # Validate attributes
    attributes = inventory.get('attributes', {})
    if not isinstance(attributes, dict):
        raise TypeError("Inventory 'attributes' must be a dictionary")
    for name, attr_def in attributes.items():
        if not isinstance(attr_def, dict):
            raise TypeError(f"Attribute definition for '{name}' must be a dictionary")
        if 'type' not in attr_def:
            raise ValueError(f"Attribute '{name}' must have a 'type' key")

    # Validate types
    types = inventory.get('types', {})
    if not isinstance(types, dict):
        raise TypeError("Inventory 'types' must be a dictionary")
    # (Further type-specific checks could be added here as needed)

    # If all checks pass, return True indicating a valid inventory
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Validate input types
        if not isinstance(manifest_files, dict):
            raise TypeError("manifest_files must be a dict")
        if not isinstance(digests_used, (set, list, tuple)):
            raise TypeError("digests_used must be an iterable of digests")
        digests_used_set = set(digests_used)

        # Build mapping from digest to the set of files that contain it
        digest_to_files = {}
        for file_path, info in manifest_files.items():
            if not isinstance(info, dict):
                continue
            digest = info.get("digest")
            if not digest:
                continue
            digest_to_files.setdefault(digest, set()).add(file_path)

        # Check that every required digest in the manifest is used
        for digest, files in digest_to_files.items():
            # Consider a digest required if any file that lists it has the 'required' flag set
            required = any(
                isinstance(manifest_files.get(f), dict) and
                manifest_files[f].get("required", False)
                for f in files
            )
            if required and digest not in digests_used_set:
                raise ValueError(
                    f"Required digest '{digest}' for files {sorted(files)} was not used."
                )

        # Check that every used digest appears in the manifest
        for digest in digests_used_set:
            if digest not in digest_to_files:
                raise ValueError(
                    f"Digest '{digest}' was used but is not present in the manifest."
                )

        # If no problems were found, return True (or simply exit without error)
        return True

