def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic input validation
    if not isinstance(inventory, (dict, list)):
        raise TypeError("inventory must be a dict or list of dicts")

    # Retrieve the entry corresponding to the requested version
    entry_data = None
    if isinstance(inventory, dict):
        entry_data = inventory.get(version)
        if entry_data is None:
            raise KeyError(f"Version {version!r} not found in inventory")
    else:  # list of dicts
        for item in inventory:
            if isinstance(item, dict) and item.get('version') == version:
                entry_data = item.get('content')
                break
        if entry_data is None:
            raise KeyError(f"Version {version!r} not found in inventory list")

    if not isinstance(entry_data, dict):
        raise ValueError(f"Inventory data for version {version!r} must be a mapping of logical paths to files")

    logical_to_files = {}
    for logical_path, file_ref in entry_data.items():
        if logical_path is None:
            continue
        try:
            # Normalize the value into a set of file references
            if isinstance(file_ref, (set, tuple, list)):
                files = set(file_ref)
            else:
                files = {file_ref}
        except Exception as exc:
            raise ValueError(f"Unable to interpret file references for logical path {logical_path!r}") from exc

        logical_to_files[logical_path] = files

    return logical_to_files

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Ensure fixity is a dictionary
        if not isinstance(fixity, dict):
            raise TypeError(f"fixity must be a dict, got {type(fixity).__name__}")

        # The expected key is 'hash'
        if 'hash' not in fixity:
            raise ValueError("fixity block is missing required 'hash' key")

        hash_entries = fixity['hash']
        if not isinstance(hash_entries, list):
            raise TypeError("fixity['hash'] must be a list")

        # Ensure manifest_files is an iterable of strings (paths)
        if not hasattr(manifest_files, '__iter__'):
            raise TypeError("manifest_files must be an iterable of file paths")

        # Iterate over each entry and validate structure and reference
        for idx, entry in enumerate(hash_entries):
            if not isinstance(entry, dict):
                raise TypeError(f"Entry {idx} in fixity['hash'] must be a dict, got {type(entry).__name__}")

            # Each entry must have a 'path' key
            if 'path' not in entry:
                raise ValueError(f"Entry {idx} in fixity['hash'] missing required 'path' key")

            path = entry['path']
            if not isinstance(path, str):
                raise TypeError(f"Entry {idx} in fixity['hash']['path'] must be a str; got {type(path).__name__}")

            # Check that the path exists in the manifest
            if path not in manifest_files:
                raise ValueError(f"File '{path}' from fixity block is not present in the manifest")

            # Optional: check that a 'value' (hash value) exists
            if 'value' not in entry:
                raise ValueError(f"Entry {idx} in fixity['hash'] missing required 'value' key")

        # If all checks pass, return True
        return True

def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    source : str
        Base path or source identifier (unused in grouping but retained for compatibility).
    xmls : list
        List of XML file paths.
    files : list
        List of files in the folder or zipfile.

    Returns
    -------
    dict
        key: name of the XML files (basename without extension)
        value: list of file paths that share the same basename
    """
    import os

    # Validate parameters
    if not isinstance(xmls, (list, tuple)):
        raise TypeError("xmls must be a list or tuple of XML file paths")
    if not isinstance(files, (list, tuple)):
        raise TypeError("files must be a list or tuple of file paths")

    # Build a mapping from basename to XML file path
    xml_map = {}
    for xml in xmls:
        try:
            base = os.path.splitext(os.path.basename(xml))[0]
        except Exception as exc:
            raise ValueError(f"Invalid XML filename: {xml}") from exc
        xml_map[base] = xml

    # Group files by basename
    grouped = {}
    for fpath in files:
        try:
            base = os.path.splitext(os.path.basename(fpath))[0]
        except Exception:
            continue  # skip any invalid paths
        if base in xml_map:
            grouped.setdefault(base, []).append(fpath)

    # Ensure that the XML file itself appears first in each list
    for base, xml_path in xml_map.items():
        if base not in grouped:
            grouped[base] = [xml_path]
        else:
            if xml_path not in grouped[base]:
                grouped[base].insert(0, xml_path)

    return grouped

