            except Exception:
                continue
            # We group by basename; include only files that have an xml counterpart
            if ext.lower() != ".xml":
                continue
            fullpath = os.path.join(root, fname)
            data.setdefault(basename, []).append(fullpath)
    return data

def add_rendition(self, lang, file_path):
        """
        {
            "original": "artigo02.pdf",
            "en": "artigo02-en.pdf",
        }
        """
        # Validate inputs
        if not isinstance(lang, str):
            raise TypeError(f"lang must be a str, got {type(lang).__name__}")
        if not isinstance(file_path, str):
            raise TypeError(f"file_path must be a str, got {type(file_path).__name__}")

        # Ensure the container for renditions exists
        if not hasattr(self, "renditions") or self.renditions is None:
            self.renditions = {}

        # Prevent duplicate renditions for the same language
        if lang in self.renditions:
            raise ValueError(f"A rendition for language '{lang}' has already been added.")

        # Store the rendition
        self.renditions[lang] = file_path

        # Optional: Return the added path for confirmation
        return self.renditions[lang]

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        raise TypeError(f"content must be a string, got {type(content).__name__}")
