def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None:
        return None
    if not isinstance(pubdate_xpaths, (list, tuple)):
        raise TypeError("pubdate_xpaths must be a list or tuple")
    for xpath in pubdate_xpaths:
        try:
            matches = node.xpath(xpath)
            if matches:
                return matches[0]
        except Exception:
            # ignore malformed xpath or evaluation error and try next
            continue
    return None

def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    import re

    if issue is None:
        return None, None

    try:
        # Obtain the text content of the element
        if hasattr(issue, "text"):
            text = issue.text
        else:
            text = str(issue)
        if text is None:
            return None, None
        text = text.strip()
        if not text:
            return None, None

        # Normalize spaces and punctuation
        text = re.sub(r"[(),.;]+", "", text)
        text = re.sub(r"\s+", " ", text)

        # Try to match a number (with optional range) at the beginning
        m = re.match(r"^(\d+(?:-\d+)?)\s+([A-Za-z].*)$", text, re.IGNORECASE)
        if m:
            num_str, sup = m.group(1), m.group(2)
            # Convert simple numbers to int
            if "-" in num_str:
                number = num_str
            else:
                try:
                    number = int(num_str)
                except ValueError:
                    number = None
            return number, sup.strip()

        # If the string starts with letters only
        m = re.match(r"^[A-Za-z].*$", text)
        if m:
            return None, text.strip()

        # Fallback: find a number anywhere in the string
        m = re.search(r"\d+", text)
        if m:
            num_str = m.group()
            sup = text.replace(num_str, "", 1).strip()
            try:
                number = int(num_str)
            except ValueError:
                number = None
            return number, sup

        # No recognizable pattern
        return None, None

    except Exception:
        # In case of any unexpected error, return None values
        return None, None

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    # Base representation: class name and optional id
    prefix = " " * indent + self.__class__.__name__
    if getattr(self, "id", None):
        prefix += f" id='{self.id}'"
    if debug:
        prefix += f" (obj=0x{id(self):x})"

    # Add a short summary of public attributes (except common ones)
    public_attrs = []
    for name, value in vars(self).items():
        if name.startswith("_") or name in ("id", "doc", "parent"):
            continue
        public_attrs.append(f"{name}={value!r}")
    if public_attrs:
        prefix += " [" + ", ".join(public_attrs) + "]"

    result = prefix

    # Recurse into child elements if any
    try:
        children = list(self)
    except TypeError:
        # Consider the object non-iterable
        children = []

    for child in children:
        # Support objects that have a pretty() method
        pretty_method = getattr(child, "pretty", None)
        if callable(pretty_method):
            result += "\n" + pretty_method(indent + 2, debug)
        else:
            # Fallback: simple representation
            child_repr = f"{' ' * (indent + 2)}{repr(child)}"
            result += "\n" + child_repr

    return result

def on(self, hook):
        """Decorator function to add a new handler to the registry.

        Args:
            hook (HookType): Hook attribute for which to register the handler.

        Returns:
            callable: Decorator for registering listeners for the specified
            hook.

        """
        if hook is None:
            raise ValueError("Hook cannot be None")

        # Ensure the registry exists on the instance
        if not hasattr(self, "_hook_registry"):
            self._hook_registry = {}

        def decorator(fn):
            if not callable(fn):
                raise TypeError("Registered handler must be a callable")

            # Add the function to the list for this hook
            if hook in self._hook_registry:
                self._hook_registry[hook].append(fn)
            else:
                self._hook_registry[hook] = [fn]

            return fn

        return decorator

def base_config(user, etcd_host="localhost", etcd_port=2379):
    """Creates a configuration with some simple parameters, which have a default value
    that can be set.

    Args:
        user (str): the name of the user for the static authentication
        etcd_host (str): the host for the database.
        etcd_port (int): the port for the database.

    Returns:
        dict: the created configuration.
    """

    if not isinstance(user, str) or not user:
        raise ValueError("Argument 'user' must be a non-empty string.")
    if not isinstance(etcd_host, str) or not etcd_host:
        raise ValueError("Argument 'etcd_host' must be a non-empty string.")
    if not isinstance(etcd_port, int) or etcd_port <= 0 or etcd_port > 65535:
        raise ValueError("Argument 'etcd_port' must be an integer between 1 and 65535.")

    config = {
        "user": user,
        "etcd": {
            "host": etcd_host,
            "port": etcd_port
        }
    }
    return config

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    _is_py2 = sys.version_info[0] == 2

    def wrapper(*args, **kwargs):
        try:
            tzname = namefunc(*args, **kwargs)
        except Exception as exc:
            # propagate other errors unchanged
            raise

        if _is_py2 and isinstance(tzname, unicode):
            try:
                # Prefer utf-8 encoding; fall back to 'ascii' if necessary
                return tzname.encode('utf-8')
            except Exception:
                try:
                    return tzname.encode('ascii', 'ignore')
                except Exception:
                    # As a last resort, return the original unicode string
                    return tzname
        return tzname

    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    # Default values used when we cannot obtain real version info
    default = {"version": "0.0.0", "full-revisionid": "unknown", "dirty": False}
    try:
        # Prefer importlib.metadata (Python 3.8+) but support backports
        try:
            from importlib.metadata import version, PackageNotFoundError
        except ImportError:
            from importlib_metadata import version, PackageNotFoundError  # type: ignore
    except Exception:
        return default

    try:
        # Try to determine the top-level package name from the module's __name__
        pkg_name = __name__.split('.')[0]
        ver_str = version(pkg_name)
    except Exception:
        return default
    else:
        return {"version": ver_str, "full-revisionid": "unknown", "dirty": False}

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # validate input
    if pieces is None:
        raise ValueError("pieces cannot be None")
    if not isinstance(pieces, (list, tuple)):
        # allow any iterable
        try:
            pieces = list(pieces)
        except TypeError:
            raise TypeError("pieces must be an iterable of renderable items")
    if style is None:
        raise ValueError("style cannot be None")

    st = str(style).lower()
    try:
        if st == "string":
            # join all pieces directly into a single string
            return "".join(str(p) for p in pieces)
        elif st == "json":
            # serialize the pieces to JSON
            import json
            return json.dumps([str(p) for p in pieces])
        elif st == "list":
            # return a copy of the pieces as a list
            return list(pieces)
        else:
            # Unsupported style
            raise ValueError(f"Unsupported style: {style!r}")
    except Exception as exc:
        # re‑raise with a clearer message
        raise RuntimeError(f"Failed to render pieces with style={style!r}") from exc

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    # Validate that pieces is an iterable
    try:
        iter(pieces)
    except TypeError:
        raise TypeError("pieces must be an iterable of elements")

    # Search for an existing '+' in any element
    for element in pieces:
        # Convert element to string to perform a safe containment check
        if '+' in str(element):
            return '.'

    # If no '+' was found, return '+'
    return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess, os, shlex

    # Build command
    if isinstance(commands, str):
        cmd = commands
        shell = True
    else:
        if not isinstance(commands, (list, tuple)):
            raise TypeError("commands must be a str or a list/tuple of command arguments")
        if not commands:
            raise ValueError("commands list cannot be empty")
        cmd = list(commands)
        if args:
            if not isinstance(args, (list, tuple)):
                raise TypeError("args must be a list or tuple")
            cmd += list(args)
        shell = False

    # Prepare environment
    env_dict = os.environ.copy()
    if env is not None:
        if not isinstance(env, dict):
            raise TypeError("env must be a dict or None")
        env_dict.update(env)

    # Handle stderr visibility
    stderr = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env_dict,
            shell=shell,
            stdout=subprocess.PIPE,
            stderr=stderr,
            text=True,
            check=True
        )
        if verbose:
            print(result.stdout, end="")
        return result.stdout
    except subprocess.CalledProcessError as exc:
        msg = f"Command '{cmd}' failed with return code {exc.returncode}"
        if verbose and exc.stdout:
            print(exc.stdout, end="")
        raise RuntimeError(msg) from exc
    except Exception as exc:
        raise RuntimeError(f"Error running command '{cmd}': {exc}") from exc

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    def _iterate(node):
        # Yield the node itself
        yield node
        # Attempt to iterate children if possible
        try:
            children = getattr(node, 'children', None)
            if children is None:
                children = getattr(node, '_children', None)
            if children is not None:
                for child in children:
                    yield from _iterate(child)
        except Exception:
            # If no children or iteration fails, skip
            return

    num_objects = 0
    good_objects = 0

    for obj in _iterate(self):
        num_objects += 1
        all_ok = True

        if validate_objects:
            try:
                obj.validate()
            except Exception as e:
                all_ok = False
                if show_warnings:
                    print(f"Warning: validation failed for {obj!r} ({e})")
                else:
                    # Re‑raise to stop processing if not in warning mode
                    raise

        if check_digests:
            try:
                # Assume a digest() method returns a bool indicating validity
                has_digest = getattr(obj, 'digest', None)
                if has_digest and callable(has_digest):
                    if not obj.digest():
                        all_ok = False
                        if show_warnings:
                            print(f"Warning: digest check failed for {obj!r}")
                else:
                    # No digest method: treat as invalid if check requested
                    all_ok = False
                    if show_warnings:
                        print(f"Warning: no digest method on {obj!r}")
            except Exception as e:
                all_ok = False
                if show_warnings:
                    print(f"Warning: digest check raised for {obj!r} ({e})")
                else:
                    raise

        if all_ok:
            good_objects += 1

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    try:
        # Ensure the root directory exists
        if not os.path.isdir(self.root):
            os.makedirs(self.root, exist_ok=True)

        # Core sub‑directories required by OCFL
        subdirs = ['objects', 'objects_all', 'receipts']
        for sub in subdirs:
            path = os.path.join(self.root, sub)
            if not os.path.isdir(path):
                os.makedirs(path, exist_ok=True)

        # Create a minimal configuration file if one does not exist
        config_path = os.path.join(self.root, '.ocfl')
        if not os.path.isfile(config_path):
            with open(config_path, 'w') as cfg:
                cfg.write('# OCFL storage root configuration\n')

    except Exception as exc:
        raise RuntimeError(
            f"Failed to initialize OCFL storage root at {self.root!r}: {exc}"
        ) from exc

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    parts = version.split('.')
    last = parts[-1]

    # Ensure the last part is numeric
    if not last.isdigit():
        raise ValueError("Cannot determine next version: the last part is not numeric")

    # Preserve leading zero width
    width = len(last)

    try:
        new_num = int(last) + 1
    except ValueError:
        raise ValueError("Invalid numeric value in version string")

    new_last = str(new_num).zfill(width) if width > 0 else str(new_num)
    parts[-1] = new_last
    return '.'.join(parts)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import xml.etree.ElementTree as ET

    # Helper to turn an inventory XML root into a pathname->digest dict
    def _inventory_to_map(root):
        mapping = {}
        for file_el in root.findall('.//file'):
            # try common attribute names used for path and digest
            path = file_el.get('path') or file_el.get('href') or file_el.get('id')
            digest = file_el.get('md5') or file_el.get('digest')
            if path and digest:
                mapping[path] = digest
        return mapping

    # Validate argument type
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")

    # Determine the root inventory file (assumed to be in the base document directory)
    root_inv_path = os.path.join(self.base_dir, self.INVENTORY_FILENAME)
    if not os.path.isfile(root_inv_path):
        raise FileNotFoundError(f"Root inventory file missing: {root_inv_path}")

    try:
        root_tree = ET.parse(root_inv_path)
        root_root = root_tree.getroot()
    except ET.ParseError as e:
        raise ValueError(f"Unable to parse root inventory XML ({root_inv_path}): {e}")

    root_digests = _inventory_to_map(root_root)

    inconsistent = {}

    for dir_name in version_dirs:
        inv_path = os.path.join(self.base_dir, dir_name, self.INVENTORY_FILENAME)
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory missing for version directory '{dir_name}': {inv_path}")

        try:
            tree = ET.parse(inv_path)
            inv_root = tree.getroot()
        except ET.ParseError as e:
            raise ValueError(f"Unable to parse inventory XML ({inv_path}): {e}")

        current_digests = _inventory_to_map(inv_root)

        # Find mismatched or missing digests relative to the root inventory
        mismatches = []
        for path, cur_digest in current_digests.items():
            root_digest = root_digests.get(path)
            if root_digest is None:
                mismatches.append((path, None, cur_digest))
            elif root_digest != cur_digest:
                mismatches.append((path, root_digest, cur_digest))

        # Also note any files present in the root but missing in this version
        for path, root_digest in root_digests.items():
            if path not in current_digests:
                mismatches.append((path, root_digest, None))

        if mismatches:
            inconsistent[dir_name] = mismatches

    # Store the discrepancies for later validation checks

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper function to deep merge two MappingNode instances
    def _merge_mapping_nodes(m1, m2):
        if not (isinstance(m1, ruamel.yaml.nodes.MappingNode) and isinstance(m2, ruamel.yaml.nodes.MappingNode)):
            return m2  # if either is not a mapping, keep m2 (last wins)
        new_items = []
        key_index = {}
        # first populate with items from m1
        for idx, (k_node, v_node) in enumerate(m1.value):
            key_str = k_node.value
            new_items.append((k_node, v_node))
            key_index[key_str] = idx
        # now merge items from m2
        for k_node, v_node in m2.value:
            key_str = k_node.value
            if key_str in key_index:
                # duplicate key found, need to merge
                existing_idx = key_index[key_str]
                existing_v = new_items[existing_idx][1]
                if isinstance(existing_v, ruamel.yaml.nodes.MappingNode) and isinstance(v_node, ruamel.yaml.nodes.MappingNode):
                    merged = _merge_mapping_nodes(existing_v, v_node)
                    new_items[existing_idx] = (k_node, merged)
                else:
                    # last wins
                    new_items[existing_idx] = (k_node, v_node)
            else:
                new_items.append((k_node, v_node))
                key_index[key_str] = len(new_items) - 1
        return ruamel.yaml.nodes.MappingNode(tag=m1.tag, value=new_items)

    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list of (ScalarNode, Node) tuples')
    # Ordered result: keep first occurrence order
    key_order = []
    key_map = {}  # key string -> (ScalarNode, value Node)
    for key_node, val_node in nodes:
        if not hasattr(key_node, 'value'):
            raise ValueError('Key node does not have a value attribute')
        key_str = key_node.value
        if key_str not in key_map:
            key_order.append(key_str)
            key_map[key_str

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Ensure the object behaves like a parser
    if not hasattr(parser, '_actions'):
        raise TypeError('Expected an argparse.ArgumentParser instance')

    flags = []
    seen = set()
    for action in parser._actions:
        # Each action may have multiple option strings (e.g., ['-v', '--verbose'])
        option_strings = getattr(action, 'option_strings', ())
        for flag in option_strings:
            if flag not in seen:
                seen.add(flag)
                flags.append(flag)

    return ' '.join(flags)

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a
    space-separated string.
    """
    if not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance")
    flags = []
    for action in parser._actions:
        # `option_strings` holds the flag names for option actions.
        if getattr(action, "option_strings", None):
            flags.extend(action.option_strings)
    return " ".join(flags)

