def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a list or tuple of strings")
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict mapping name to ArgumentParser")

    parsed = {}
    unknownsets = []

    for name, parser in subparsers.items():
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f"Value for key '{name}' must be an ArgumentParser instance")
        try:
            ns, rem = parser.parse_known_args(unparsed_arguments)
        except Exception as exc:
            # Preserve traceback for debugging, but re-raise as ValueError
            raise ValueError(f"Error while parsing arguments with subparser '{name}': {exc}") from exc
        parsed[name] = ns
        unknownsets.append(set(rem))

    if unknownsets:
        remaining = set.intersection(*unknownsets)
    else:
        remaining = set()

    return parsed, list(remaining)

def _dictsum(dicts):
    """Combine values of the dictionaries supplied by iterable dicts.

    Example:
        >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
        {'a': 6, 'b': 2}
    """
    try:
        iter(dicts)
    except TypeError:
        raise TypeError("The 'dicts' argument must be an iterable of dictionaries") from None

    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Each element must be a dict, got {type(d).__name__}")
        for key, value in d.items():
            if key in result:
                try:
                    result[key] += value
                except TypeError as exc:
                    raise ValueError(
                        f"Cannot add value of key {key!r} "
                        f"({value!r}) with existing value {result[key]!r}"
                    ) from exc
            else:
                result[key] = value
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # If the value is actually None, consider it a None-like representation
    if val is None:
        return True

    # Only strings can be "representing" a None value
    if not isinstance(val, str):
        return False

    # Normalize string: remove whitespace and lower-case
    s = val.strip().lower()

    # Common textual representations of a null/none value
    return s in ('', 'none', 'null', 'nil', 'nan', 'empty')

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Basic validation
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non‑negative")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple of strings, got {type(alphabet).__name__}")
    if len(alphabet) <= 1:
        raise ValueError("alphabet must contain at least two symbols")
    for i, sym in enumerate(alphabet):
        if not isinstance(sym, str):
            raise TypeError(f"alphabet[{i}] must be a str, got {type(sym).__name__}")
        if len(sym) != 1:
            raise ValueError(f"alphabet[{i}] must be a single character")

    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non‑negative")

    base = len(alphabet)
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        digits.reverse()

    # Apply padding if requested
    if padding is not None and len(digits) < padding:
        padding_needed = padding - len(digits)
        digits = [alphabet[0]] * padding_needed + digits

    return ''.join(digits)

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if register_number is None:
        raise ValueError("register_number cannot be None")
    if register_value is None:
        raise ValueError("register_value cannot be None")

    def _replace_recursive(d):
        new_d = {}
        for k, v in d.items():
            new_key = register_number if k == register_value else k
            # If the new key already exists we cannot overwrite it
            if new_key in new_d and new_key != k:
                raise KeyError(f"Duplicate key '{new_key}' found when replacing '{register_value}'")
            new_val = _replace_recursive(v) if isinstance(v, dict) else v
            new_d[new_key] = new_val
        return new_d

    return _replace_recursive(flow_params)

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""

    # Validate input types
    if not isinstance(value, str):
        raise TypeError(f"value must be a str, got {type(value).__name__}")
    if not isinstance(arg, str):
        raise TypeError(f"arg must be a str, got {type(arg).__name__}")

    try:
        return value.replace('.', arg)
    except Exception as exc:
        raise RuntimeError(f"Error replacing dots: {exc}") from exc

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string:
        raise ValueError("Input string must not be empty.")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two symbols.")
    # Map each character in the alphabet to its numeric value
    alphabet_map = {ch: i for i, ch in enumerate(alphabet)}
    num = 0
    for ch in string:
        if ch not in alphabet_map:
            raise ValueError(f"Character '{ch}' not found in alphabet.")
        num = num * base + alphabet_map[ch]
    return num

