def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise TypeError(f"Expected a dict, got {type(item).__name__}")

    result = {}
    for key, value in item.items():
        if not isinstance(key, str):
            raise TypeError(f"Dictionary key {key!r} is not a string")
        # Build a regex pattern that matches the wildcard pattern.
        # '*' -> '.*', '?' -> '.', escape regex special characters.
        parts = []
        for ch in key:
            if ch == '*':
                parts.append('.*')
            elif ch == '?':
                parts.append('.')
            elif ch in ('.', '^', '$', '+', '{', '}', '[', ']', '|', '(', ')', '\\'):
                parts.append(f'\\{ch}')
            else:
                parts.append(ch)
        regex_key = '^' + ''.join(parts) + '$'
        result[regex_key] = value
    return result

import re
def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Remove leading or trailing single/double quotes, if any
    return re.sub(r"(^['\"])|(['\"])$", "", name)

def addignored(ignored=None):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    import os
    # Validate the path if provided
    cwd = None
    if ignored is not None:
        if not isinstance(ignored, str):
            raise TypeError(f"ignored must be a string path or None, not {type(ignored).__name__}")
        if not os.path.isdir(ignored):
            raise FileNotFoundError(f"Directory {ignored} does not exist")
        cwd = ignored

    try:
        # Run git to list ignored files
        output = subprocess.check_output(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            cwd=cwd,
            stderr=subprocess.STDOUT,
            universal_newlines=True
        )
    except subprocess.CalledProcessError:
        # git command failed (e.g., not a repository)
        return ''
    except FileNotFoundError:
        # git not installed
        return ''

    # Process output
    files = [line.strip() for line in output.splitlines() if line.strip()]
    files.sort()
    return ','.join(files)

def match(filename):
    """Check if the filename is a type that this module supports

    Args:
        filename: Filename to match
    Returns:
        False if not a match, True if supported
    """
    try:
        if not isinstance(filename, str):
            return False
        _, ext = os.path.splitext(filename)
        return ext.lower() in {'.xml', '.json', '.folia'}
    except Exception:
        return False

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Handle None or special value "always"
    if frequency is None or (isinstance(frequency, str) and frequency.strip().lower() == "always"):
        return None

    if not isinstance(frequency, str):
        raise ValueError(f"frequency must be a string, got {type(frequency).__name__}")

    # Strip leading/trailing whitespace
    freq = frequency.strip()

    # Pattern to capture an integer number followed by a time unit
    try:
        import re
    except ImportError:
        raise RuntimeError("regular expression module 're' is required")

    pattern = r'^\s*(\d+)\s*(\w+)\s*$'
    match = re.match(pattern, freq)
    if not match:
        raise ValueError(f"Could not parse frequency '{frequency}'. Expected format '<number> <unit>'")

    amount_str, unit = match.groups()
    try:
        amount = int(amount_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency '{frequency}'")

    unit = unit.lower()
    if unit in ("day", "days"):
        return datetime.timedelta(days=amount)
    if unit in ("week", "weeks"):
        return datetime.timedelta(weeks=amount)
    if unit in ("hour", "hours"):
        return datetime.timedelta(hours=amount)
    if unit in ("minute", "minutes"):
        return datetime.timedelta(minutes=amount)
    if unit in ("second", "seconds"):
        return datetime.timedelta(seconds=amount)

    raise ValueError(f"Unknown time unit '{unit}' in frequency '{frequency}'")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or IP
    :return: True if the host is the localhost
    """
    if host is None:
        raise ValueError("host must not be None")

    # Normalize the host string
    host = host.strip()
    if not host:
        raise ValueError("host must be a non-empty string")

    try:
        # Resolve the host to a list of addresses
        addrinfo = socket.getaddrinfo(host, None, proto=socket.IPPROTO_TCP)
    except socket.gaierror:
        # Could not resolve the hostname
        return False
    except Exception as e:
        # Unexpected error, re-raise to avoid silent failures
        raise e

    for family, _, _, _, sockaddr in addrinfo:
        # IPv4 check: family == socket.AF_INET
        if family == socket.AF_INET:
            ip = sockaddr[0]
            # Check if IPv4 loopback
            if ip.startswith("127.") or ip == "0.0.0.0":
                return True
        # IPv6 check: family == socket.AF_INET6
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            # Check standard IPv6 loopback ::1
            if ip == "::1":
                return True

    return False

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    # Quick sanity check: only relevant on Windows
    if os.name != 'nt':
        return False

    try:
        ostype = os.environ.get('OSTYPE', '').lower()
    except Exception:
        # In unlikely event that environment access fails
        return False

    # Git Bash typically sets OSTYPE to msys
    if 'msys' in ostype:
        return True

    # Some build scripts might set MSYSTEM instead of OSTYPE
    try:
        if 'MSYSTEM' in os.environ:
            return True
    except Exception:
        pass

    return False

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Extract name and optional default from matcher
    if isinstance(matcher, (list, tuple)):
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    else:
        name, default = matcher, None

    # Lookup environment variable
    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        raise KeyError(
            f"Environment variable {name!r} not set and no default provided"
        )
    return value

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not isinstance(image_href, str):
        raise ValueError(f"image_href must be a string, got {type(image_href).__name__}")
    image_href = image_href.strip()
    if not image_href:
        raise ValueError("image_href is empty")

    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as exc:
        raise ValueError(f"Invalid image_href '{image_href}': {exc}") from exc

    # Determine use_ssl based on https scheme
    use_ssl = parsed.scheme.lower() == "https"

    # If there is a scheme, consider it a full URL
    if parsed.scheme:
        netloc = parsed.netloc
        # Extract image_id from the path; use the last path component
        # Strip trailing slashes to avoid empty component
        path = parsed.path.rstrip("/")
        if path:
            image_id = path.rsplit("/", 1)[-1]
        else:
            # If path is empty, try query for 'id' parameter
            query_params = urllib.parse.parse_qs(parsed.query)
            # Pick first value for key 'id', else raise error
            if "id" in query_params and query_params["id"]:
                image_id = query_params["id"][0]
            else:
                raise ValueError(f"Could not determine image_id from URL: {image_href}")
    else:
        # No scheme: treat entire string as image_id; no netloc; use_ssl False
        netloc = ""
        image_id = image_href

    if not image_id:
        raise ValueError(f"Could not parse image_id from href: {image_href}")

    return (image_id, netloc, use_ssl)

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    if not isinstance(pattern, str):
        raise TypeError('pattern must be a string')
    if strip:
        pattern = pattern.strip()
    # Escape all regex special characters
    escaped = re.escape(pattern)
    try:
        return re.compile(escaped)
    except re.error as e:
        raise ValueError(f'Invalid regex pattern: {escaped}') from e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    import os
    # Normalize command inputs
    if isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        cmd_list = [commands]

    if args is None:
        args_list = []
    elif isinstance(args, (list, tuple)):
        args_list = list(args)
    else:
        raise TypeError("args must be a list or tuple of strings")

    # Validate cwd
    if cwd is not None and not os.path.isdir(cwd):
        raise ValueError(f"The working directory '{cwd}' does not exist or is not a directory")

    # Ensure environment is a dict if provided
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dictionary of environment variables")

    final_output = ""

    for cmd in cmd_list:
        if not isinstance(cmd, str):
            raise TypeError("Each command must be a string")

        # Build the full command list
        full_cmd = [cmd] + args_list

        if verbose:
            print(f"Running: {' '.join(full_cmd)}")

        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env,
                cwd=cwd,
                check=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
            )

            final_output = result.stdout  # keep only the last command's output
            if not hide_stderr and result.stderr:
                sys.stderr.write(result.stderr)

        except subprocess.CalledProcessError as e:
            err_msg = e.stderr if not hide_stderr else ""
            raise RuntimeError(
                f"Command '{e.cmd[0]}' failed with return code {e.returncode}. "
                f"Error: {err_msg}"
            ) from e
        except OSError as e:
            raise RuntimeError(f"Failed to execute command '{cmd}': {e}") from e

    return final_output

