import sys
def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    # Use the provided dumper if given, otherwise default to yaml.safe_dump
    if dumper is None:
        dumper = yaml.safe_dump
    try:
        data = dumper(obj)
    except TypeError:
        # If the dumper is a class, use it as a YAML Dumper argument
        data = yaml.safe_dump(obj, Dumper=dumper)
    # Ensure the returned value is a text string across Python 2 and 3
    if sys.version_info[0] < 3:
        if isinstance(data, bytes):
            try:
                return data.decode('utf-8')
            except Exception:
                return data.decode('latin1')
        return data
    return data

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        x_arr = np.asarray(x)
        mu = 0.2
        sigma = 0.1
        return np.exp(-((x_arr - mu) ** 2) / (2 * sigma ** 2))
    except Exception as e:
        raise ValueError(f"Invalid input to gaussian: {e}")

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json
    try:
        import yaml
    except ImportError:  # YAML not available
        yaml = None

    configs = {}
    errors = []

    if overrides is not None and not isinstance(overrides, dict):
        raise TypeError(f"overrides must be a dict if provided, got {type(overrides).__name__}")

    def _resolve_env_vars(obj):
        if isinstance(obj, dict):
            return {k: _resolve_env_vars(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_resolve_env_vars(v) for v in obj]
        if isinstance(obj, str):
            import os
            # simple environment variable interpolation ${VAR}
            import re
            pattern = re.compile(r'\$\{([^}]+)\}')
            def repl(match):
                return os.getenv(match.group(1), match.group(0))
            return pattern.sub(repl, obj)
        return obj

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                ext = filename.rsplit('.', 1)[-1].lower()
                if ext == 'json':
                    config = json.load(f)
                elif ext in ('yaml', 'yml') and yaml is not None:
                    config = yaml.safe_load(f)
                else:
                    # fallback: try JSON
                    try:
                        config = json.load(f)
                    except Exception:
                        raise ValueError(f"Unsupported file format for '{filename}' and no parser available.")
                if not isinstance(config, dict):
                    raise ValueError(f"Configuration file '{filename}' must contain a top-level dictionary.")
                if overrides:
                    config.update(overrides)
                if resolve_env:
                    config = _resolve_env_vars(config)
                configs[filename] = config
        except Exception as exc:
            record = logging.LogRecord(
                name=__name__,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Failed to load configuration '{filename}': {exc}",
                args=(),
                exc_info=None
            )
            errors.append(record)

    return configs, errors

def force_string(obj):
    """This function returns the bytes object corresponding to ``obj`` in case it is a string using UTF-8."""
    if isinstance(obj, str):
        try:
            return obj.encode('utf-8')
        except Exception as e:
            raise ValueError(f"Failed to encode string to bytes: {e}") from e
    return obj

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If already a sequence type we use it as is (but return a list for mutability)
    if isinstance(seq, (list, tuple, set, frozenset)):
        # Preserve original type information
        return (list(seq), type(seq))
    if isinstance(seq, str):
        # Strings are sequences of characters but usually we keep them as-is
        return (seq, str)

    # For other iterables, attempt to consume into a list
    try:
        iterator = iter(seq)
    except TypeError:
        raise TypeError("Provided object is not iterable")

    # Import only when needed to keep namespace clean
    import itertools

    if bufsize is not None:
        if not isinstance(bufsize, int) or bufsize < 0:
            raise ValueError("bufsize must be a non‑negative integer or None")
        seq_list = list(itertools.islice(iterator, bufsize))
    else:
        seq_list = list(iterator)

    return (seq_list, type(seq_list))

def scale(self, other=None, recompute=False):
        """Compute or set scale (integral of the histogram).

        If *other* is ``None``, return scale of this histogram.
        If its scale was not computed before,
        it is computed and stored for subsequent use
        (unless explicitly asked to *recompute*).
        Note that after changing (filling) the histogram
        one must explicitly recompute the scale
        if it was computed before.

        If a float *other* is provided, rescale self to *other*.

        Histograms with scale equal to zero can't be rescaled.
        :exc:`.LenaValueError` is raised if one tries to do that.
        """
        # Helper to compute integral of the histogram.
        def _compute_integral():
            try:
                # Most histograms are iterable over bin counts.
                return sum(self)
            except TypeError:
                # Fallback: if the object has a `values()` method.
                try:
                    return sum(v for v in self.values())
                except Exception:
                    raise ValueError(
                        "Cannot compute scale: histogram is not iterable or lacks values()"
                    )

        # Return current scale.
        if other is None:
            if not hasattr(self, "_scale") or recompute or self._scale is None:
                self._scale = _compute_integral()
            return self._scale

        # Rescale the histogram.
        try:
            new_scale = float(other)
        except Exception:
            raise TypeError("Parameter 'other' must be a number")

        # Ensure current scale is known.
        if not hasattr(self, "_scale") or recompute or self._scale is None:
            self._scale = _compute_integral()

        if self._scale == 0:
            raise LenaValueError(
                "Histograms with scale equal to zero cannot be rescaled."
            )

        factor = new_scale / self._scale

        # Scale each bin count; assume histogram supports item assignment.
        try:
            for i in range(len(self)):
                old = self[i]
                self[i] = int(round(old * factor))
        except Exception:
            # If the histogram cannot be altered in-place, raise an error.
            raise RuntimeError("Failed to rescale the histogram bins.")

        # Update stored scale.
        self._scale = new_scale
        return self._scale

def scale(self, other=None):
        """Get or set the scale of the graph.

        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        # Helper to ensure a numeric value
        def _to_float(val):
            try:
                return float(val)
            except Exception:
                raise TypeError(f"Scale value {val!r} is not numeric")

        if other is None:
            # Return current scale: try to compute from stored attributes if not yet set
            if not hasattr(self, "_scale") or self._scale is None:
                # Attempt to infer scale from stored data
                try:
                    if hasattr(self, "size") and isinstance(self.size, (list, tuple)):
                        self._scale = self.size[-1] - 1
                    elif hasattr(self, "fields"):
                        # If size not available, try to deduce from last field length
                        last_field = getattr(self, self.fields[-1], None)
                        if isinstance(last_field, (list, tuple)):
                            self._scale = len(last_field) - 1
                except Exception:
                    self._scale = None
            if self._scale is None or self._scale == 0:
                raise ValueError("Scale is unknown or zero for the graph.")
            return self._scale

        # If a numeric other is provided, resize / rescale the last field
        new_scale = _to_float(other)
        if new_scale <= 0:
            raise ValueError("Scale must be positive and non‑zero.")

        # Rescale the last coordinate field
        if hasattr(self, "fields") and self.fields:
            last_idx = len(self.fields) - 1
            field_name = self.fields[last_idx]
            try:
                last_field = getattr(self, field_name)
            except Exception:
                raise AttributeError(f"Field {field_name!r} not found on the graph")
            if not isinstance(last_field, (list, tuple)):
                raise TypeError(f"Field {field_name!r} is not a sequence")
            # Determine current scale
            cur_scale = getattr(self, "_scale", None)
            if cur_scale is None:
                # Attempt to compute current scale from this field's length
                cur_scale = len(last_field) - 1
            if cur_scale == 0:
                raise ValueError("Current scale is zero, cannot rescale.")
            factor = new_scale / cur_scale
            # Apply factor to each element in the last field
            try:
                for i, val in enumerate(last_field):
                    last_field[i] = val * factor
            except Exception as exc:
                raise ValueError(f"Error while rescaling data: {exc}")
            # Update stored scale
            self._scale = new_scale
        else:
            raise AttributeError("The graph has no fields to rescale.")
        # Nothing to return for setting scale
        return None

def hist_to_graph(hist, make_value=None, get_coordinate="left",
