def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is provided, use it directly
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"Explicit metaclass {explicit_mc!r} is not a type")
        return explicit_mc

    # Gather the metaclasses of all bases
    mcls_set = set()
    for base in bases:
        if not isinstance(base, type):
            raise TypeError(f"Base {base!r} is not a class")
        mcls_set.add(type(base))

    if not mcls_set:
        # No bases provided, fall back to the default metaclass
        return type

    # Choose the most derived metaclass that is a subclass of all others
    candidate = None
    for mcls in mcls_set:
        if all(issubclass(mcls, other) for other in mcls_set if other is not mcls):
            if candidate is not None:
                # Two distinct metaclasses that are not related in the hierarchy
                raise TypeError(f"Metaclass conflict between {candidate.__name__} and {mcls.__name__}")
            candidate = mcls

    if candidate is None:
        raise TypeError(f"Could not determine a unique metaclass from bases: {bases!r}")

    return candidate

def pop(self, key, default=__marker):
        """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
        If key is not found, d is returned if given, otherwise KeyError is raised.
        """
        try:
            # Attempt to retrieve and delete the key in one operation if the underlying
            # storage supports a fast pop, otherwise do the operations separately.
            try:
                value = self._data.pop(key)
                return value
            except AttributeError:
                # Fallback: use the mapping interface
                if key in self:
                    value = self[key]
                    del self[key]
                    return value
                else:
                    raise KeyError(key)
        except KeyError:
            # Key was not present
            if default is __marker:
                raise
            return default

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")

    # Try to determine the least‑frequently used key.
    try:
        # If a `freq` mapping is provided, use it; otherwise default to 0.
        freq = getattr(self, "freq", {})
        min_key = min(self, key=lambda k: freq.get(k, 0))
    except Exception as exc:
        raise KeyError("popitem(): failed to determine least frequent item") from exc

    # Remove the key from both the dictionary and the frequency map.
    try:
        value = self.pop(min_key)
    except Exception as exc:
        raise KeyError(f"popitem(): failed to remove key '{min_key}'") from exc

    # Clean up the frequency entry if present.
    if isinstance(freq, dict):
        freq.pop(min_key, None)

    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    try:
        # Retrieve the first key (assumed to be the least recently used)
        key = next(iter(self))
    except StopIteration as exc:
        raise KeyError("popitem(): unable to determine LRU key") from exc
    try:
        value = self[key]
    except KeyError as exc:
        # In case of concurrent modification
        raise KeyError(f"popitem(): key '{key}' not found") from exc
    try:
        del self[key]
    except KeyError as exc:
        raise KeyError(f"popitem(): failed to delete key '{key}'") from exc
    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Verify this is a mutable mapping.
    if not hasattr(self, "popitem"):
        raise TypeError("popitem() requires a mutable mapping")

    # Try the efficient popitem(last=True) if available (OrderedDict, recent dict)
    try:
        return self.popitem(last=True)
    except TypeError:
        # Fallback for plain dict or older implementations:
        # Pop the most recently inserted key.
        try:
            key = next(reversed(self))
        except StopIteration:
            # The container is empty
            raise KeyError("popitem(): dictionary is empty")
        # Remove and return the key/value pair
        return key, self.pop(key)

def _create_in_regex(self) -> Pattern:
    """Create the in‑style parameter regular expression.

    Returns the in‑style parameter regular expression (:class:`re.Pattern`).
    """
    import re
    try:
        # Matches: in:<value> , where value cannot contain commas or whitespace
        pattern = r'\bin\s*:\s*(?P<value>[^,\s]+)'
        return re.compile(pattern)
    except re.error as exc:
        # Re‑raise as a RuntimeError with context for easier debugging
        raise RuntimeError(f"Could not compile in‑style regex: {exc}") from exc

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        # Check for a public message attribute
        if hasattr(request, "public_message") and request.public_message is not None:
            return True
        # Check for a private message attribute
        if hasattr(request, "private_message") and request.private_message is not None:
            return True
        # Check for a legacy payload indicator
        if hasattr(request, "payload") and isinstance(request.payload, dict):
            if request.payload.get("type") == "legacy":
                return True
        # Not a Diaspora request
        return False
    except Exception:
        # If request doesn't expose the expected attributes we cannot confirm
        return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Exact type check first
        if isinstance(request, RequestType):
            # If the request has a 'type' attribute we compare it
            if hasattr(request, "type"):
                return str(request.type).lower() == "matrix"
            # If the request is a mapping with a 'type' key
            if isinstance(request, dict) and "type" in request:
                return str(request["type"]).lower() == "matrix"

        # Handle the common case where the request is a simple string
        if isinstance(request, str):
            return request.strip().lower() == "matrix"

        # Not a matrix request in any recognised form
        return False
    except Exception:
        # Unexpected issues should simply return False rather than raise
        return False

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    if replacer is not None and not callable(replacer):
        raise TypeError("replacer must be callable or None")

    # Find code block spans (`` ` `` or `` ``` ``)
    code_block_pattern = re.compile(r'(```.*?```|`.*?`)', re.DOTALL | re.MULTILINE)
    code_blocks = []
    for m in code_block_pattern.finditer(text):
        code_blocks.append((m.start(), m.end()))

    def in_code_block(pos):
        for start, end in code_blocks:
            if start <= pos < end:
                return True
        return False

    tag_pattern = re.compile(r'#(\w+)\b')
    tags = set()
    parts = []
    last_end = 0

    for m in tag_pattern.finditer(text):
        start, end = m.start(), m.end()
        if in_code_block(start):
            continue
        tags.add(m.group(1))
        parts.append(text[last_end:start])
        if replacer:
            try:
                replacement = replacer(m.group(1))
            except Exception:
                replacement = m.group(0)
            if replacement is None:
                replacement = m.group(0)
            else:
                replacement = str(replacement)
            parts.append(replacement)
        else:
            parts.append(m.group(0))
        last_end = end

    parts.append(text[last_end:])
    new_text = ''.join(parts)

    return tags, new_text

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    if not isinstance(url, str) or not url.strip():
        return None
    try:
        # Import inside the function to avoid top-level imports
        from urllib.request import Request, urlopen
        from urllib.error import URLError, HTTPError

        req = Request(url, method="HEAD")
        with urlopen(req, timeout=10) as response:
            return response.headers.get("Content-Type")
    except (URLError, HTTPError, ValueError):
        return None
    except Exception:
        return None

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        raise ValueError("Provided node is None")
    try:
        children = list(node)
    except TypeError:
        raise TypeError("Expected an Element-like object with iterable children")

    result = {}
    for child in children:
        tag = getattr(child, 'tag', None)
        if tag is None:
            continue
        if tag in result:
            # If this is the first duplicate, convert to list
            if not isinstance(result[tag], list):
                result[tag] = [result[tag]]
            result[tag].append(child)
        else:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if not (url.startswith("http://") or url.startswith("https://")):
        raise ValueError("url must start with http:// or https://")

    if document_path is not None:
        if not isinstance(document_path, str):
            raise ValueError("document_path must be a string if provided")
        if not document_path.startswith("/"):
            document_path = "/" + document_path
        full_path = url.rstrip("/") + document_path
    else:
        full_path = url.rstrip("/") + "/.well-known/nodeinfo"

    # Minimal NodeInfo document structure
    nodeinfo = {
        "software": {
            "name": "Placeholder",
            "version": "1.0",
        },
        "protocols": ["activitypub"],
        "services": {},
        "nodes": [
            {
                "software": {
                    "name": "Placeholder",
                    "version": "1.0",
                },
                "services": {},
                "protocols": ["activitypub"],
                "nodeUri": full_path,
            }
        ],
        "protocol": "nodeinfo",
        "links": [
            {
                "rel": "self",
                "href": full_path,
                "type": "application/json",
            }
        ],
    }

    return nodeinfo

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    if not isinstance(document, str):
        raise TypeError("document must be a string containing the webfinger data")

    doc = document.strip()
    if not doc:
        raise ValueError("Empty webfinger document")

    # Try JSON first (new format)
    try:
        data = json.loads(doc)
        # Ensure key structure is flattened for consistency
        result: Dict = {}
        # Copy top-level keys except "links" if present
        for k, v in data.items():
            if k.lower() == "links":
                result["links"] = v
            else:
                result[k] = v
        return result
    except json.JSONDecodeError:
        pass

    # Fallback to XRD (old format)
    try:
        root = ET.fromstring(doc)
        ns = {"xrd": root.tag.split("}")[0].strip("{")} if "{" in root.tag else {}
        result: Dict = {}

        # Subject element
        subject = root.find("xrd:Subject", ns) if ns else root.find("Subject")
        if subject is not None:
            result["subject"] = subject.text or ""

        # Alias elements
        aliases = []
        for alias in root.findall("xrd:Alias", ns) if ns else root.findall("Alias"):
            if alias.text:
                aliases.append(alias.text)
        result["aliases"] = aliases

        # Link elements
        links = []
        for link in root.findall("xrd:Link", ns) if ns else root.findall("Link"):
            rel = link.attrib.get("rel") or link.attrib.get("xmlns")  # fallback
            href = link.attrib.get("href")
            if rel and href:
                links.append({"rel": rel, "href": href})
        result["links"] = links

        return result
    except ET.ParseError as exc:
        raise ValueError("Could not parse webfinger document as JSON or XRD") from exc

    # If we reach here something unexpected happened
    raise RuntimeError("Unexpected error while parsing webfinger document")

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        if not handle or '@' not in handle:
            return None
        domain = handle.split('@', 1)[1]
        resource = urllib.parse.quote(f'acct:{handle}')
        url = f'https://{domain}/.well-known/webfinger?resource={resource}'
        with urllib.request.urlopen(url, timeout=5) as resp:
            return resp.read().decode('utf-8')
    except Exception:
        return None

def retrieve_diaspora_host_meta(host):
    """Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import urllib.request
    import urllib.error
    import ssl
    import xml.etree.ElementTree as ET

    # Helper to perform a request and return the XML root
    def _fetch_xml(url):
        req = urllib.request.Request(url, headers={'Accept': 'application/xrd+xml'})
        ctx = ssl.create_default_context()
        # Some servers may have self‑signed certs; ignore verification for host‑meta
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
        with urllib.request.urlopen(req, context=ctx, timeout=10) as resp:
            if resp.status != 200:
                raise urllib.error.HTTPError(url, resp.status, resp.reason, resp.headers, None)
            data = resp.read()
            return ET.fromstring(data)

    # Try HTTPS first, then HTTP
    for scheme in ('https://', 'http://'):
        url = f"{scheme}{host}/.well-known/host‑meta"
        try:
            root = _fetch_xml(url)
            # Assume the XRD class can be instantiated from the parsed XML element
            if hasattr(root, 'tag') and root.tag.endswith('xrd'):
                # Try to import XRD from common library if available
                try:
                    from xrd import XRD  # type: ignore
                except Exception:
                    XRD = None
                if XRD:
                    return XRD(root)
                else:
                    return root  # Return ElementTree element if XRD class not available
            else:
                raise ValueError(f"Unexpected root element: {root.tag}")
        except (urllib.error.URLError, urllib.error.HTTPError, ssl.SSLError, ET.ParseError, ValueError):
            # If the request fails or parsing fails, try the next scheme
            continue

    raise RuntimeError(f"Could not retrieve a valid host‑meta document from {host}")

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    # validate input
    if not isinstance(dic, dict):
        raise TypeError(f"dic must be a dict, got {type(dic)!r}")

    # Build the full key chain
    if not keys:
        # if only key is provided, it might be a sequence of keys
        if isinstance(key, (list, tuple)):
            chain = list(key)
        else:
            chain = [key]
    else:
        chain = [key] + list(keys)

    if not chain:
        raise ValueError("No keys provided for insertion")

    # Traverse or create intermediate dictionaries
    current = dic
    for part in chain[:-1]:
        if not isinstance(part, str):
            raise TypeError(f"All keys must be strings, got {type(part)!r}")
        if part not in current or not isinstance(current[part], dict):
            current[part] = {}
        current = current[part]

    # Insert the final value
    final_key = chain[-1]
    if not isinstance(final_key, str):
        raise TypeError(f"Final key must be a string, got {type(final_key)!r}")
    current[final_key] = val
    return dic

@classmethod
    def ansible_config_manager(cls):
        """Gets the ansible config manager. """
        # Lazy creation of the manager instance
        if not hasattr(cls, "_ansible_config_manager"):
            try:
                # Try to access Ansible's configuration utilities
                from ansible import constants as ACON
                class _AnsibleConfigManager:
                    """Simple wrapper around Ansible constants."""
                    def __init__(self):
                        self.constants = ACON
                    def get(self, name, default=None):
                        return getattr(self.constants, name, default)
                cls._ansible_config_manager = _AnsibleConfigManager()
            except Exception:  # Ansible not available or import failed
                # Fall back to a very small in-memory manager
                class _SimpleConfigManager:
                    """Fallback configuration manager."""
                    def __init__(self):
                        self._data = {}
                    def get(self, name, default=None):
                        return self._data.get(name, default)
                    def set(self, name, value):
                        self._data[name] = value
                cls._ansible_config_manager = _SimpleConfigManager()
        return cls._ansible_config_manager

