@classmethod
def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    Parameters:
        spec_content (str or dict, optional): content of spec file
    Raises:
        IRValidatorException: when mandatory data is missing in spec file
    Returns:
        dict: Dictionary with data loaded from a spec (YAML) file
    """
    # ensure spec_content is provided
    if spec_content is None:
        raise IRValidatorException("Spec content is missing.")

    # load content if it is a string; otherwise assume it is already a dict
    if isinstance(spec_content, str):
        try:
            import yaml
            spec_data = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(f"Failed to parse YAML content: {exc}") from exc
    else:
        spec_data = spec_content

    # verify that we got a dictionary
    if not isinstance(spec_data, dict):
        raise IRValidatorException(
            f"Spec content must be a mapping (dict), got {type(spec_data).__name__}."
        )

    # define mandatory fields (example set, modify as needed)
    mandatory_fields = ("name", "version", "description")

    missing = [fld for fld in mandatory_fields if fld not in spec_data]
    if missing:
        raise IRValidatorException(
            f"Spec is missing mandatory field(s): {', '.join(missing)}."
        )

    return spec_data

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if not yaml_file:
            raise IRValidatorException("No yaml_file path provided")
        # Ensure the file exists
        try:
            import os
            if not os.path.isfile(yaml_file):
                raise FileNotFoundError(f"YAML file not found: {yaml_file}")
        except Exception as e:
            raise IRValidatorException(f"Error accessing YAML file: {e}") from e

        # Load the YAML file
        try:
            import yaml
            with open(yaml_file, "r", encoding="utf-8") as fh:
                data = yaml.safe_load(fh)
        except Exception as e:
            raise IRValidatorException(f"Error parsing YAML file: {e}") from e

        if not isinstance(data, dict):
            raise IRValidatorException("YAML root element must be a mapping (dict)")

        # Validate required keys if the class defines them
        required_fields = getattr(cls, "REQUIRED_FIELDS", None)
        if required_fields:
            missing = [field for field in required_fields if field not in data]
            if missing:
                raise IRValidatorException(
                    f"Missing required field(s) in YAML: {', '.join(missing)}"
                )

        return data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        # 1. Pull defaults from the instance's spec attribute if it exists
        spec = getattr(self, "spec", None)
        if isinstance(spec, dict):
            for key, value in spec.items():
                # Many specs use a nested dict with a 'default' key
                if isinstance(value, dict) and "default" in value:
                    defaults[key] = value["default"]
                else:
                    # Assume direct default values
                    defaults[key] = value

        # 2. Merge in class‑wide defaults defined as class attributes
        # (e.g., Annotations might define DEFAULT_foo = 42)
        for attr, val in getattr(self.__class__, "__dict__", {}).items():
            if attr.startswith(("DEFAULT_", "DEFAULT")) and val is not None:
                # strip the 'DEFAULT_' prefix for consistency
                key = attr.replace("DEFAULT_", "", 1).lower()
                defaults.setdefault(key, val)

        # 3. Finally, populate any remaining expected args from __annotations__
        annotations = getattr(self.__class__, "__annotations__", {})
        for key in annotations:
            if key not in defaults and hasattr(self, key):
                defaults[key] = getattr(self, key)

    except Exception as exc:
        # If anything goes wrong, return an empty dict but don't crash the caller
        # logging could be added here in a real application
        defaults = {}

    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    # If the instance already has a predefined mapping of deprecated options
    # use that, otherwise return an empty dictionary.
    if hasattr(self, "deprecated_args"):
        try:
            mapping = dict(self.deprecated_args)
            if isinstance(mapping, dict):
                return mapping
        except Exception:
            # ignore unexpected types or conversion errors
            pass
    return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        import sys
        # A set or list of deprecated argument names can be defined on the instance.
        deprecated = set(getattr(self, 'deprecated_args', []))
        # Helper to process a source of arguments
        def _check(source_name, args):
            for key in list(args.keys()):
                if key in deprecated:
                    msg = f"[WARN] Deprecated argument '{key}' used from {source_name} arguments."
                    # Prefer standard error, but fall back to stdout if needed
                    try:
                        print(msg, file=sys.stderr)
                    except Exception:
                        print(msg, file=sys.stdout)
                # Optional: remove deprecated args after warning to avoid further processing
                # args.pop(key, None)

        try:
            _check('CLI', cli_args)
        except Exception as exc:
            # If something odd happens while checking CLI args, log and continue
            try:
                print(f"[ERROR] Failed to validate CLI deprecated arguments: {exc}", file=sys.stderr)
            except Exception:
                pass

        try:
            _check('Answer File', answer_file_args)
        except Exception as exc:
            try:
                print(f"[ERROR] Failed to validate answer file deprecated arguments: {exc}", file=sys.stderr)
            except Exception:
                pass

        # No explicit return value required; the method is for side-effect (logging).

def get_parser_option_specs(self, command_name):
        """Gets all the options for the specified command

        :param command_name: the command name (main, virsh, ospd, etc...)
        :return: the list of all command options
        """
        # Validate input
        if not isinstance(command_name, str):
            raise TypeError("command_name must be a string")

        # Attempt to locate the command in the parser
        cmd_obj = None
        try:
            # Common patterns for command registries
            if hasattr(self, "parser"):
                if hasattr(self.parser, "get"):
                    cmd_obj = self.parser.get(command_name)
                elif hasattr(self.parser, "commands"):
                    cmd_obj = self.parser.commands.get(command_name)
                elif hasattr(self.parser, command_name):
                    cmd_obj = getattr(self.parser, command_name)
            # Fall back to a simple dict attribute
            if cmd_obj is None and hasattr(self, "commands"):
                cmd_obj = self.commands.get(command_name)
        except Exception:
            # If any unexpected error occurs while retrieving the command, ignore and continue
            cmd_obj = None

        if cmd_obj is None:
            raise KeyError(f"Command '{command_name}' not found")

        # Retrieve the options from the command object
        options = None
        try:
            options = getattr(cmd_obj, "options", None)
        except Exception:
            options = None

        # If options attribute is not found, try a common method name
        if options is None:
            try:
                options = getattr(cmd_obj, "get_options", lambda: None)()
            except Exception:
                options = None

        # If still unavailable, try a parser-level helper
        if options is None:
            try:
                options = getattr(self.parser, "options_for", lambda _: None)(command_name)
            except Exception:
                options = []

        # Ensure we return a list
        if options is None:
            options = []
        if not isinstance(options, list):
            try:
                options = list(options)
            except Exception:
                options = [options]

        return options

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate argument types
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")

    # Retrieve the command object
    try:
        command = self.commands[command_name]
    except KeyError as exc:
        raise ValueError(f"Command '{command_name}' not found.") from exc

    # Retrieve the option specification from the command
    try:
        return command.options[argument_name]
    except KeyError as exc:
        raise ValueError(f"Option '{argument_name}' not found in command '{command_name}'.") from exc

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    silent = []
    try:
        # Support dict or any iterable of (name, value) pairs
        if isinstance(args, dict):
            items = args.items()
        else:
            items = args

        for name, value in items:
            # Consider an argument "silenced" if its value is None or an empty string
            if value is None or value == '':
                silent.append(name)
    except Exception:
        # If input is not iterable or other unexpected types, return an empty list
        silent = []

    return silent

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Determine the list of mandatory arguments defined for this instance.
    required = getattr(self, 'REQUIRED_ARGS', None)
    if not required:
        # Nothing mandatory to check
        return
    # Normalise `args` to a dictionary for easier lookup
    if args is None:
        args_dict = {}
    elif isinstance(args, dict):
        args_dict = args
    else:
        # If a non-dict is supplied (e.g., a list/tuple), convert it to a dict
        # using positional mapping based on `REQUIRED_ARGS`. Any additional
        # items are ignored.
        try:
            args_dict = {name: value for name, value in zip(required, args)}
        except Exception:
            raise ValueError("Arguments must be a dictionary or a sequence matching REQUIRED_ARGS.")

    missing = [name for name in required if name not in args_dict or args_dict[name] is None]

    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        # Basic validation
        if command_name is None:
            raise ValueError("command_name cannot be None")
        if options_spec is None:
            raise ValueError("options_spec cannot be None")
        if args is None:
            args = {}
        if not isinstance(args, dict):
            raise TypeError("args must be a mapping of option names to values")

        required = []

        for opt in options_spec:
            # Try to obtain the option's identifier; support dict or object
            if isinstance(opt, dict):
                name = opt.get("name") or opt.get("arg") or opt.get("option")
                cond = opt.get("required_when")
            else:
                # Assume object with attributes
                name = getattr(opt, "name", None) or getattr(opt, "arg", None) or getattr(opt, "option", None)
                cond = getattr(opt, "required_when", None)

            if not name or cond is None:
                continue

            # Helper to evaluate condition
            def matches_condition(cond_value):
                if isinstance(cond_value, bool):
                    return cond_value
                if isinstance(cond_value, dict):
                    return all(args.get(k) == v for k, v in cond_value.items())
                if isinstance(cond_value, (list, tuple)):
                    # Support list of tuples or dicts
                    for item in cond_value:
                        if isinstance(item, dict):
                            if not all(args.get(k) == v for k, v in item.items()):
                                return False
                        elif isinstance(item, (list, tuple)) and len(item) == 2:
                            k, v = item
                            if args.get(k) != v:
                                return False
                        else:
                            return False
                    return True
                if callable(cond_value):
                    try:
                        return bool(cond_value(args))
                    except Exception:
                        return False
                # Unknown condition type
                return False

            if matches_condition(cond):
                required.append(name)

        return required

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments. Can be a dict or an iterable of
            values. The method will check that the length of each value (if it
            implements ``__len__``) does not exceed ``self.length``.
        """
        # Lookup the maximum allowed length
        max_len = getattr(self, "length", None)
        if max_len is None:
            raise AttributeError(
                f"{self.__class__.__name__} instance has no 'length' attribute"
            )
        if not isinstance(max_len, int) or max_len < 0:
            raise ValueError(f"'length' must be a non‑negative integer, got {max_len!r}")

        # Helper to validate a single item
        def _check_item(name, value):
            try:
                l = len(value)
            except TypeError:
                return  # value has no length; skip
            if l > max_len:
                raise ValueError(
                    f"Argument '{name}' length {l} exceeds maximum allowed {max_len}"
                )

        # Accept a dictionary or an iterable
        if isinstance(args, dict):
            for key, value in args.items():
                _check_item(str(key), value)
        elif isinstance(args, (list, tuple)):
            for idx, value in enumerate(args):
                _check_item(f"arg[{idx}]", value)
        else:
            raise TypeError("args must be a dict or an (ordered) list/tuple")
        # Return True to indicate success
        return True

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError(f"Expected args to be dict, got {type(args).__name__}")
    # Get mapping of argument names to allowed choices.
    # Subclasses may provide this as ``choices`` or ``arg_choices``.
    choice_map = getattr(self, "choices", None) or getattr(self, "arg_choices", None)
    if choice_map is None:
        # No choices defined, nothing to validate
        return
    if not isinstance(choice_map, dict):
        raise TypeError("Choice mapping must be a dict mapping arg names to allowed values")
    for key, val in args.items():
        if key not in choice_map:
            continue  # no validation rule for this arg
        allowed = choice_map[key]
        if not isinstance(allowed, (list, tuple, set)):
            raise TypeError(f"Choices for argument '{key}' must be a list/tuple/set, got {type(allowed).__name__}")
        # Accept ``None`` as valid null value by default
        if val is None:
            continue
        # If the argument value itself is an iterable (except string/bytes), treat each element.
        if isinstance(val, (list, tuple, set)) and not isinstance(val, (str, bytes)):
            for item in val:
                if item not in allowed:
                    raise ValueError(
                        f"Invalid value '{item}' for argument '{key}'. Allowed: {allowed}"
                    )
        else:
            if val not in allowed:
                raise ValueError(
                    f"Invalid value '{val}' for argument '{key}'. Allowed: {allowed}"
                )

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        # args is expected to be an iterable of 4-tuples: (name, value, min_val, max_val)
        if args is None:
            return True
        try:
            for item in args:
                if not isinstance(item, (list, tuple)):
                    raise ValueError(f"Argument specification {item!r} is not a tuple or list.")
                if len(item) != 4:
                    raise ValueError(f"Argument specification {item!r} must contain exactly four elements (name, value, min, max).")
                name, value, min_val, max_val = item
                if value is None:
                    raise ValueError(f"Argument '{name}' has no value (None).")
                if not (min_val <= value <= max_val):
                    raise ValueError(f"Argument '{name}' value {value} out of bounds [{min_val}, {max_val}].")
            return True
        except Exception as e:
            # Re-raise as ValueError for consistent error type
            raise ValueError(f"Invalid arguments: {e}") from e

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Known prefixes that indicate control arguments
    CONTROL_PREFIXES = ('_', 'control_', 'verbose', 'debug', 'quiet', 'dry_run')

    # Helper to parse individual argument strings
    def _parse_arg(arg):
        if isinstance(arg, str) and '=' in arg:
            key, val = arg.split('=', 1)
            return key.strip(), val.strip()
        if isinstance(arg, tuple) and len(arg) == 2:
            return str(arg[0]).strip(), str(arg[1]).strip()
        return None, None

    try:
        # If args is a mapping, iterate its items directly
        if isinstance(args, dict):
            items = args.items()
        else:
            # Assume a sequence (list/tuple) of strings or tuples
            items = []
            for item in args:
                key, val = _parse_arg(item)
                if key is not None:
                    items.append((key, val))
    except Exception:
        # Fallback: return empty dicts if parsing fails
        return {}, {}

    for key, val in items:
        if any(key.startswith(pref) for pref in CONTROL_PREFIXES):
            control_args[key] = val
        else:
            # Treat everything else as a nested argument
            nested_args[key] = val

    return control_args, nested_args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        # Validate the input dictionary
        if not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

        # Nothing to merge when extra_vars is falsy
        if not extra_vars:
            return

        # Accept list/tuple or single string/dict
        if isinstance(extra_vars, (str, dict)):
            extra_vars = [extra_vars]
        elif not hasattr(extra_vars, '__iter__'):  # non-iterable
            raise TypeError(f"extra_vars must be an iterable of key-value definitions, got {type(extra_vars).__name__}")

        for item in extra_vars:
            # Skip None values
            if item is None:
                continue

            if isinstance(item, dict):
                # Merge key/value pairs
                vars_dict.update(item)
            elif isinstance(item, str):
                # Expect format "key=value"
                if '=' not in item:
                    raise ValueError(f"Invalid extra var string, expected 'key=value': {item!r}")
                key, val = item.split('=', 1)
                vars_dict[key] = val
            else:
                raise TypeError(f"Unsupported type in extra_vars: expected dict or 'key=value' string, got {type(item).__name__}")

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import json
    import subprocess

    if not playbook_path:
        raise ValueError("playbook_path must be provided")

    # Build base command
    cmd = ["ansible-playbook"]

    # Add verbosity
    if verbose is not None:
        try:
            v_level = int(verbose)
        except Exception:
            v_level = 0
        if v_level > 0:
            cmd.append("-" + "v" * v_level)

    # Playbook path
    cmd.append(playbook_path)

    # Extra variables
    if extra_vars:
        cmd.extend(["--extra-vars", json.dumps(extra_vars)])

    # Additional ansible-playbook arguments
    if ansible_args:
        if isinstance(ansible_args, dict):
            for key, value in ansible_args.items():
                if value is None:
                    # flag only
                    cmd.append(key)
                else:
                    cmd.extend([key, str(value)])
        elif isinstance(ansible_args, (list, tuple)):
            cmd.extend(ansible_args)
        else:
            raise ValueError("ansible_args must be a dict or list/tuple")

    # Run command in workspace directory if available
    cwd = getattr(ir_workspace, "path", None)

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            check=True,
            capture_output=True,
            text=True,
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook command not found") from exc
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(
            f"ansible-playbook exited with code {exc.returncode}:\n{exc.stderr}"
        ) from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected error while running ansible-playbook: {exc}") from exc

    # Return output and error streams (stderr may contain warnings)
    return result.stdout, result.stderr

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # Mapping of argument names to expected types; subclasses can populate
        # `self.arg_type_map` as a {parser_name: {arg_name: type}} dictionary.
        type_map = getattr(self, "arg_type_map", {}).get(parser_name, {})

        def _convert(val, tgt_type):
            if tgt_type is bool:
                if isinstance(val, bool):
                    return val
                if isinstance(val, str):
                    lowered = val.strip().lower()
                    if lowered in ("true", "t", "yes", "y", "1"):
                        return True
                    if lowered in ("false", "f", "no", "n", "0"):
                        return False
                raise ValueError(f"Cannot convert '{val}' to bool")
            try:
                return tgt_type(val)
            except Exception as exc:
                raise ValueError(f"Cannot convert '{val}' to {tgt_type.__name__}") from exc

        for key, val in list(values_dict.items()):
            expected_type = type_map.get(key)
            if expected_type is not None:
                try:
                    values_dict[key] = _convert(val, expected_type)
                except ValueError as e:
                    # Re‑raise with contextual information
                    raise ValueError(f"Argument '{key}' conversion error: {e}") from e

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Validate input
    if not isinstance(plugin_dir, str) or not plugin_dir.strip():
        raise ValueError("plugin_dir must be a non‑empty string path")

    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"The directory '{plugin_dir}' does not exist")

    # Locate the spec file (fall back from plugin.json to spec.json)
    spec_candidates = ("plugin.json", "spec.json")
    spec_path = None
    for name in spec_candidates:
        potential = os.path.join(plugin_dir, name)
        if os.path.isfile(potential):
            spec_path = potential
            break

    if spec_path is None:
        raise FileNotFoundError(f"No spec file found in '{plugin_dir}'. Expected one of {spec_candidates}")

    # Load JSON with error handling
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            spec_data = json.load(f)
    except json.JSONDecodeError as exc:
        raise ValueError(f"Malformed JSON in spec file '{spec_path}': {exc}") from exc
    except OSError as exc:
        raise RuntimeError(f"Unable to read spec file '{spec_path}': {exc}") from exc

    # Helper to flatten nested dicts
    def _flatten(current, parent_key=""):
        flat = {}
        for key, value in current.items():
            new_key = f"{parent_key}{key}" if not parent_key else f"{parent_key}.{key}"
            if isinstance(value, dict):
                flat.update(_flatten(value, new_key))
            else:
                flat[new_key] = value
        return flat

    return _flatten(spec_data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        import os
        env_var = "CONFIG_PATH"
        # Only set if not already defined
        if env_var not in os.environ:
            # Prefer an attribute on this instance if present
            config_path = getattr(self, "config_path", None)
            # Fallback to a sensible default if no attribute or empty
            if not config_path:
                config_path = "/etc/myapp/config"
            os.environ[env_var] = config_path
    except Exception as exc:
        raise RuntimeError(f"Unable to inject configuration path: {exc}") from exc

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if path is None or root is None:
        raise TypeError("Both path and root must be provided")
    # Normalize both inputs
    path = os.path.normpath(path)
    root = os.path.normpath(root)

    try:
        # os.path.relpath will raise ValueError if path cannot be expressed relative to root
        rel_path = os.path.relpath(path, root)
    except ValueError as exc:
        raise ValueError(
            f"Unable to remove root '{root}' from path '{path}': "
            "path is not under the specified root."
        ) from exc

    # If the resulting relative path is just '.', it means path==root
    if rel_path == os.curdir:
        return ''
    return rel_path
